INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt", translations) VALUES ('cms5cw342000752bh8b5g83mg', 'tlp-pipeline', 'cms5cw33x000552bh17r6zfov', 'TLP Pipeline', 'TLP Pipeline S.A.', 'TLP Pipeline develops, builds and operates large-diameter pipeline systems and associated pumping and terminal infrastructure for water, mining concentrates and hydrocarbons across Latin America. The group manages a multi-country project pipeline and procures equipment, EPC capacity and specialized services at scale for its concession portfolio.', 'infrastructure', 'Brazil', 'BR', 'São Paulo', NULL, 1987, 4200, NULL, true, true, '2026-07-29 00:38:18.818', '2026-07-29 00:38:18.818', '{"es":{"description":"TLP Pipeline desarrolla, construye y opera sistemas de tuberías de gran diámetro e infraestructura asociada de bombeo y terminales para agua, concentrados mineros e hidrocarburos en América Latina. El grupo gestiona un pipeline de proyectos multinacional y contrata equipos, capacidad EPC y servicios especializados a gran escala para su portafolio de concesiones."}}');
INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt", translations) VALUES ('cms5cw34b000a52bhbwbjcu5u', 'andrade-gutierrez', 'cms5cw347000852bh66z90213', 'Andrade Gutiérrez', 'Andrade Gutiérrez Engenharia S.A.', 'Andrade Gutiérrez is one of Latin America''s largest engineering and heavy-construction groups, with seven decades of experience delivering mining, energy, sanitation and transport infrastructure across more than 40 countries. Its project teams contract equipment fleets, subcontractors and technical services for concurrent large-scale works.', 'infrastructure', 'Brazil', 'BR', 'Belo Horizonte', NULL, 1948, 18000, NULL, true, true, '2026-07-29 00:38:18.828', '2026-07-29 00:38:18.828', '{"es":{"description":"Andrade Gutiérrez es uno de los mayores grupos de ingeniería y construcción pesada de América Latina, con siete décadas de experiencia entregando infraestructura minera, energética, sanitaria y de transporte en más de 40 países. Sus equipos de proyecto contratan flotas de equipos, subcontratistas y servicios técnicos para grandes obras simultáneas."}}');
INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt", translations) VALUES ('cms5cw34j000d52bhnzfmk6l7', 'tbea', 'cms5cw34f000b52bhjosv2gxs', 'TBEA', 'TBEA Co., Ltd.', 'TBEA is a global manufacturer of power transmission and transformation equipment and a developer of energy infrastructure, with transformer, cable and polysilicon plants supplying utility-scale projects worldwide. Its international project division sources logistics, civil works and local technical partners for turnkey energy developments.', 'energy', 'China', 'CN', 'Changji', NULL, 1993, 26000, NULL, true, true, '2026-07-29 00:38:18.835', '2026-07-29 00:38:18.835', '{"es":{"description":"TBEA es un fabricante global de equipos de transmisión y transformación de energía y desarrollador de infraestructura energética, con plantas de transformadores, cables y polisilicio que abastecen proyectos utility-scale en todo el mundo. Su división internacional de proyectos contrata logística, obras civiles y socios técnicos locales para desarrollos energéticos llave en mano."}}');
INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt", translations) VALUES ('cms5cw34m000f52bh4y8sita8', 'aldridge-industrial-holdings', 'cms5cw33i000152bhh8po64vs', 'Aldridge Industrial Holdings', 'Aldridge Industrial Holdings Ltd.', 'Diversified industrial holding headquartered in the UAE, with controlling stakes in port terminals, bulk-liquids storage and manufacturing assets across the Middle East and Latin America. The group actively rotates its portfolio and develops greenfield industrial platforms alongside strategic partners.', 'ports', 'United Arab Emirates', 'AE', 'Dubai', NULL, 2004, 1350, NULL, true, false, '2026-07-29 00:38:18.838', '2026-07-29 00:38:18.838', '{"es":{"description":"Holding industrial diversificado con sede en EAU, con participaciones controladoras en terminales portuarios, almacenamiento de graneles líquidos y activos de manufactura en Medio Oriente y América Latina. El grupo rota activamente su portafolio y desarrolla plataformas industriales greenfield junto a socios estratégicos."}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw36i001452bhgephrfj1', 'andina-drilling-geotech', 'cms5cw36c001252bh4qq54ebs', 'Andina Drilling & Geotech', 'Chilean drilling and geotechnical services contractor specialized in high-altitude and remote mining environments. Full-service offering from exploration drilling to geotechnical instrumentation, with an owned fleet of 14 rigs and permanent QA/QC and safety teams.', 'technical_services', 'Chile', 'CL', 'Santiago', NULL, 380, 21, '["ISO 9001","ISO 14001","ISO 45001"]', '["68,000 m diamond & RC drilling — Vizcachas Copper Project (2019–2024)","Geotechnical campaign, 240 boreholes — coastal water pipeline (2023)","Dewatering wells program — Salar de Atacama (2021)"]', '14 drill rigs · 3 concurrent remote camps', 'PUBLISHED', true, false, NULL, '2026-07-29 00:38:18.906', '2026-07-29 00:38:18.906', '{"es":{"description":"Contratista chileno de perforación y servicios geotécnicos especializado en entornos mineros remotos y de altura. Oferta integral desde perforación de exploración hasta instrumentación geotécnica, con flota propia de 14 equipos y equipos permanentes de QA/QC y seguridad.","capacity":"14 equipos de perforación · 3 campamentos remotos simultáneos","portfolio":["68.000 m de perforación diamantina y aire reverso — Proyecto de Cobre Vizcachas (2019–2024)","Campaña geotécnica, 240 sondajes — tubería de agua costera (2023)","Programa de pozos de drenaje — Salar de Atacama (2021)"]}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw36q001752bhybyib5gk', 'skanor-epc', 'cms5cw36m001552bhzoikkdu0', 'Skanor EPC', 'European EPC contractor for water, energy and industrial infrastructure with three decades of international delivery. Strong track record in pumping and compression stations, HV substations and balance-of-plant packages under FIDIC frameworks.', 'epc', 'Spain', 'ES', 'Madrid', NULL, 2100, 34, '["ISO 9001","ISO 45001","FIDIC-experienced"]', '["4 pumping stations delivered EPC — Iberia & North Africa","220/500 kV substations, 11 projects across LatAm","Desalination balance-of-plant, 2 plants in Morocco"]', '3 concurrent EPC sites · 120 engineers in-house', 'PUBLISHED', true, true, NULL, '2026-07-29 00:38:18.915', '2026-07-29 00:38:18.915', '{"es":{"description":"Contratista EPC europeo de infraestructura hídrica, energética e industrial con tres décadas de ejecución internacional. Sólido track record en estaciones de bombeo y compresión, subestaciones de alta tensión y paquetes balance of plant bajo marcos FIDIC.","capacity":"3 obras EPC simultáneas · 120 ingenieros propios","portfolio":["4 estaciones de bombeo entregadas EPC — Iberia y Norte de África","Subestaciones 220/500 kV, 11 proyectos en LatAm","Balance of plant de desalación, 2 plantas en Marruecos"]}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw36y001a52bh6j3qlb6z', 'transandes-heavy-logistics', 'cms5cw36u001852bh7jv7lw6x', 'TransAndes Heavy Logistics', 'Heavy-lift and project-cargo specialist covering the Pacific coast and Andean corridors. Integrated route studies, bridge reinforcement, escorted convoys and port handling for out-of-gauge industrial cargo.', 'logistics', 'Chile', 'CL', 'Valparaíso', NULL, 640, 18, '["ISO 9001","ISO 39001","BASC"]', '["Transport of 12 transformers up to 260 t — Andean transmission line","Port-to-mine oversized cargo framework — 3 mining operations","SPMT operations for modular plant relocation (2022)"]', 'SPMT up to 320 t · 60-truck heavy fleet · route engineering team', 'PUBLISHED', true, false, NULL, '2026-07-29 00:38:18.922', '2026-07-29 00:38:18.922', '{"es":{"description":"Especialista en izaje pesado y carga de proyecto que cubre la costa del Pacífico y los corredores andinos. Estudios de ruta integrados, refuerzo de puentes, convoyes escoltados y manejo portuario para carga industrial sobredimensionada.","capacity":"SPMT hasta 320 t · flota pesada de 60 camiones · equipo de ingeniería de rutas","portfolio":["Transporte de 12 transformadores de hasta 260 t — línea de transmisión andina","Contrato marco puerto–mina de carga sobredimensionada — 3 operaciones mineras","Operaciones SPMT para relocalización de planta modular (2022)"]}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw374001d52bhyw8ng9k2', 'maquisur-equipment', 'cms5cw370001b52bh2w0r4vcp', 'MaquiSur Equipment', 'Andean heavy-equipment distributor and maintenance contractor. Sales, leasing and full maintenance-and-repair contracts (MARC) for off-highway fleets, with factory-certified workshops and on-site parts logistics.', 'equipment', 'Peru', 'PE', 'Lima', NULL, 890, 26, '["ISO 9001","OEM-certified dealer","MARC-experienced"]', '["MARC contracts on 4 mining fleets (availability > 89%)","Supply of 55 off-highway trucks to Andean copper operations","On-site parts warehouses at 6 remote operations"]', '5-year MARC programs · on-site technician coverage nationwide', 'PUBLISHED', true, false, NULL, '2026-07-29 00:38:18.928', '2026-07-29 00:38:18.928', '{"es":{"description":"Distribuidor andino de equipos pesados y contratista de mantenimiento. Venta, arriendo y contratos integrales de mantenimiento y reparación (MARC) para flotas fuera de carretera, con talleres certificados de fábrica y logística de repuestos en faena.","capacity":"Programas MARC a 5 años · cobertura de técnicos en faena a nivel nacional","portfolio":["Contratos MARC en 4 flotas mineras (disponibilidad > 89%)","Suministro de 55 camiones fuera de carretera a operaciones de cobre andinas","Bodegas de repuestos en faena en 6 operaciones remotas"]}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw37c001g52bhn5jvksfh', 'verdant-environmental', 'cms5cw378001e52bhib2rgze7', 'Verdant Environmental', 'Brazilian environmental consultancy focused on ports, coastal works and heavy infrastructure: impact studies, licensing management before state and federal agencies, marine monitoring and community engagement.', 'environmental', 'Brazil', 'BR', 'Rio de Janeiro', NULL, 210, 15, '["IBAMA-registered","ISO 14001"]', '["EIA and licensing — 2 container terminal expansions (Santos, Itajaí)","Marine biota monitoring, 5-year program — port dredging","Community engagement programs for 8 infrastructure projects"]', '40 licensed specialists · marine monitoring vessels on retainer', 'PUBLISHED', true, false, NULL, '2026-07-29 00:38:18.936', '2026-07-29 00:38:18.936', '{"es":{"description":"Consultora ambiental brasileña enfocada en puertos, obras costeras e infraestructura pesada: estudios de impacto, gestión de licenciamiento ante agencias estatales y federales, monitoreo marino y relacionamiento comunitario.","capacity":"40 especialistas habilitados · embarcaciones de monitoreo marino con contrato marco","portfolio":["EIA y licenciamiento — 2 expansiones de terminales de contenedores (Santos, Itajaí)","Monitoreo de biota marina, programa de 5 años — dragado portuario","Programas de relacionamiento comunitario para 8 proyectos de infraestructura"]}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw37i001j52bhbg67hiyl', 'omnigrid-om', 'cms5cw37f001h52bh62cp47tm', 'OmniGrid O&M', 'Independent operations & maintenance provider for utility-scale solar plants and HV infrastructure. Preventive and corrective programs, certified switching personnel and CMMS-based performance reporting.', 'maintenance', 'Mexico', 'MX', 'Monterrey', NULL, 460, 12, '["ISO 55001","NFPA 70E","Certified HV switching crews"]', '["O&M of 520 MW PV portfolio across Mexico and Argentina","HV substation maintenance framework — 14 substations","24/7 monitoring center with CMMS reporting"]', '520 MW under management · 24/7 NOC · thermography drones', 'PUBLISHED', true, false, NULL, '2026-07-29 00:38:18.942', '2026-07-29 00:38:18.942', '{"es":{"description":"Proveedor independiente de operación y mantenimiento para plantas solares utility-scale e infraestructura de alta tensión. Programas preventivos y correctivos, personal certificado para maniobras y reportería de desempeño basada en CMMS.","capacity":"520 MW bajo gestión · NOC 24/7 · drones de termografía","portfolio":["O&M de portafolio fotovoltaico de 520 MW en México y Argentina","Contrato marco de mantenimiento de subestaciones AT — 14 subestaciones","Centro de monitoreo 24/7 con reportería CMMS"]}}');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw37o001m52bhq8jwy4co', 'baustahl-civil-works', 'cms5cw37l001k52bhwepvqpnr', 'Baustahl Civil Works', 'Heavy civil-works and mining earthworks contractor with own fleet and experienced high-volume load & haul teams. Currently completing registry qualification.', 'construction', 'Brazil', 'BR', 'São Paulo', NULL, 1500, 22, '["ISO 9001","ISO 45001"]', '["38 Mm³ mass earthworks — iron ore expansion (2018–2021)","Haul road network, 60 km — Carajás corridor"]', 'Fleet of 45 haul units · 2 concurrent mine sites', 'IN_REVIEW', false, false, NULL, '2026-07-29 00:38:18.949', '2026-07-29 00:38:18.949', '{"es":{"description":"Contratista de obras civiles pesadas y movimiento de tierras minero con flota propia y equipos experimentados de carguío y transporte de alto volumen. Actualmente completando su calificación en el catastro.","capacity":"Flota de 45 unidades de acarreo · 2 faenas mineras simultáneas","portfolio":["38 Mm³ de movimiento masivo de tierras — expansión de mineral de hierro (2018–2021)","Red de caminos mineros, 60 km — corredor de Carajás"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw34s000h52bhlfosa6l7', 'tlp-large-diameter-pipe-supply', 'Large-diameter steel pipe supply — 180 km water transport line', 'Supply of API 5L X70 welded steel pipe (48–56 inch) with internal lining and external coating for a 180 km desalinated-water transport system in northern Chile. Staged deliveries over 22 months to two laydown yards; mill certificates and third-party inspection required for every heat.', 'equipment', 'STANDARD', 'cms5cw342000752bh8b5g83mg', 'Chile', 'CL', 'Antofagasta', 60000000, 85000000, '2026-10-15 00:00:00', '["API 5L PSL2 mill certification","Proven deliveries above 100 km of pipeline in the last 10 years","Third-party inspection (TPI) acceptance at mill","Staged delivery plan with two laydown yards"]', 'OPEN', 246, '2026-07-29 00:38:18.844', '2026-07-29 00:38:18.844', '{"es":{"title":"Suministro de tubería de acero de gran diámetro — línea de transporte de agua de 180 km","description":"Suministro de tubería de acero soldada API 5L X70 (48–56 pulgadas) con revestimiento interior y recubrimiento exterior para un sistema de transporte de agua desalada de 180 km en el norte de Chile. Entregas escalonadas durante 22 meses a dos patios de acopio; se exigen certificados de acería e inspección de tercera parte para cada colada.","requirements":["Certificación de acería API 5L PSL2","Entregas comprobadas sobre 100 km de tubería en los últimos 10 años","Aceptación de inspección de tercera parte (TPI) en acería","Plan de entregas escalonadas con dos patios de acopio"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw354000l52bhpn0pi9jm', 'tlp-oversize-logistics', 'Specialized logistics for oversized pipeline components', 'Multi-year framework for port handling, storage and overland transport of oversized pipeline components (up to 90 t single pieces) from Brazilian and Chilean ports to Andean job sites, including route studies, permits and escorted convoys.', 'logistics', 'STANDARD', 'cms5cw342000752bh8b5g83mg', 'Brazil', 'BR', 'Santos', 8000000, 15000000, '2026-09-30 00:00:00', '["Heavy-lift fleet above 80 t payload","Cross-border Andean transport experience","Cargo insurance up to USD 20M per shipment"]', 'OPEN', 68, '2026-07-29 00:38:18.856', '2026-07-29 00:38:18.856', '{"es":{"title":"Logística especializada para componentes sobredimensionados de tubería","description":"Contrato marco plurianual para manejo portuario, almacenamiento y transporte terrestre de componentes sobredimensionados de tubería (piezas únicas de hasta 90 t) desde puertos brasileños y chilenos hasta faenas andinas, incluyendo estudios de ruta, permisos y convoyes escoltados.","requirements":["Flota de izaje pesado sobre 80 t de carga útil","Experiencia en transporte transfronterizo andino","Seguro de carga hasta USD 20M por embarque"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw359000n52bhggvuctn2', 'ag-earthworks-subcontractor-iron-ore', 'Earthworks & haulage subcontractor — iron ore mine expansion', 'Mass earthworks subcontract (34 Mm³ over 30 months) for an iron ore expansion in Minas Gerais: drilling support, load & haul, haul-road maintenance and dust control. Own fleet required; fuel supplied by the main contractor at site.', 'construction', 'STANDARD', 'cms5cw34b000a52bhbwbjcu5u', 'Brazil', 'BR', 'Belo Horizonte', 25000000, 40000000, '2026-10-01 00:00:00', '["Own fleet of at least 30 haul units","Mining earthworks experience above 20 Mm³","Safety statistics (TRIFR) below industry benchmark"]', 'OPEN', 263, '2026-07-29 00:38:18.861', '2026-07-29 00:38:18.861', '{"es":{"title":"Subcontratista de movimiento de tierras y acarreo — expansión de mina de hierro","description":"Subcontrato de movimiento masivo de tierras (34 Mm³ en 30 meses) para una expansión de mineral de hierro en Minas Gerais: apoyo a perforación, carguío y transporte, mantención de caminos mineros y control de polvo. Se requiere flota propia; el combustible lo suministra el contratista principal en faena.","requirements":["Flota propia de al menos 30 unidades de acarreo","Experiencia en movimiento de tierras minero sobre 20 Mm³","Estadísticas de seguridad (TRIFR) bajo el benchmark de la industria"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw35d000p52bhi6btzmsk', 'ag-mining-truck-fleet', 'Fleet of 40 off-highway trucks with full maintenance contract', 'Purchase or long-term lease of forty 90–100 t class off-highway trucks with a 5-year MARC (maintenance and repair contract), operator training and on-site parts warehouse for two concurrent infrastructure projects in Brazil.', 'equipment', 'STANDARD', 'cms5cw34b000a52bhbwbjcu5u', 'Brazil', 'BR', NULL, 45000000, 70000000, '2026-12-15 00:00:00', '["OEM or certified dealer","MARC track record of 4+ years fleet availability above 88%","On-site parts and technician coverage"]', 'OPEN', 385, '2026-07-29 00:38:18.865', '2026-07-29 00:38:18.865', '{"es":{"title":"Flota de 40 camiones fuera de carretera con contrato de mantenimiento integral","description":"Compra o arriendo de largo plazo de cuarenta camiones fuera de carretera clase 90–100 t con contrato MARC a 5 años (mantenimiento y reparación), capacitación de operadores y bodega de repuestos en faena para dos proyectos de infraestructura simultáneos en Brasil.","requirements":["Fabricante (OEM) o distribuidor certificado","Track record MARC de 4+ años con disponibilidad de flota sobre 88%","Cobertura de repuestos y técnicos en faena"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw35i000r52bhqib4do4f', 'ag-environmental-licensing-port', 'Environmental licensing consultancy for port expansion works', 'Environmental impact studies, licensing management and community-engagement program for a container terminal expansion, including dredging permits and marine biota monitoring plans coordinated with state and federal agencies.', 'environmental', 'STANDARD', 'cms5cw34b000a52bhbwbjcu5u', 'Brazil', 'BR', 'Santos', 2000000, 5000000, '2026-09-15 00:00:00', '["Port or coastal EIA experience in Brazil","Registered with IBAMA as consultant","Marine biota monitoring capability"]', 'OPEN', 88, '2026-07-29 00:38:18.871', '2026-07-29 00:38:18.871', '{"es":{"title":"Consultoría de licenciamiento ambiental para obras de expansión portuaria","description":"Estudios de impacto ambiental, gestión de licenciamiento y programa de relacionamiento comunitario para la expansión de un terminal de contenedores, incluyendo permisos de dragado y planes de monitoreo de biota marina coordinados con las agencias estatales y federales.","requirements":["Experiencia en EIA portuarios o costeros en Brasil","Registro vigente como consultor ante IBAMA","Capacidad de monitoreo de biota marina"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw35n000t52bhc407r3v8', 'tbea-epc-substation-partner', 'Local EPC partner for 500 kV substation packages in LatAm', 'TBEA seeks local EPC partners in Chile and Argentina for the balance-of-plant and installation scope of 500 kV substation packages (civil works, erection, testing support) tied to transmission projects where TBEA supplies main transformers and HV equipment.', 'epc', 'STANDARD', 'cms5cw34j000d52bhnzfmk6l7', 'Chile', 'CL', 'Santiago', 30000000, 60000000, '2026-11-15 00:00:00', '["HV substation erection references (220 kV or above)","Local electrical contractor licenses","Capacity for two concurrent sites"]', 'OPEN', 301, '2026-07-29 00:38:18.876', '2026-07-29 00:38:18.876', '{"es":{"title":"Socio EPC local para paquetes de subestaciones de 500 kV en LatAm","description":"TBEA busca socios EPC locales en Chile y Argentina para el alcance de balance of plant y montaje de paquetes de subestaciones de 500 kV (obras civiles, montaje, apoyo a pruebas) asociados a proyectos de transmisión donde TBEA suministra los transformadores principales y el equipamiento de alta tensión.","requirements":["Referencias de montaje de subestaciones de alta tensión (220 kV o superior)","Licencias locales de contratista eléctrico","Capacidad para dos faenas simultáneas"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw35r000v52bh4zcpczak', 'tbea-transformer-logistics', 'Port-to-site logistics for power transformer deliveries', 'Framework agreement for reception, port handling and inland transport of large power transformers (up to 280 t) from Manzanillo port to project sites in central Mexico, including hydraulic platform trailers, route reinforcement works and cranage.', 'logistics', 'STANDARD', 'cms5cw34j000d52bhnzfmk6l7', 'Mexico', 'MX', 'Manzanillo', 5000000, 12000000, '2026-10-30 00:00:00', '["Hydraulic modular trailers (SPMT) above 250 t","Transformer transport references","Route survey and bridge reinforcement capability"]', 'OPEN', 381, '2026-07-29 00:38:18.879', '2026-07-29 00:38:18.879', '{"es":{"title":"Logística puerto–faena para entregas de transformadores de poder","description":"Acuerdo marco para recepción, manejo portuario y transporte terrestre de grandes transformadores de poder (hasta 280 t) desde el puerto de Manzanillo hasta faenas en el centro de México, incluyendo plataformas hidráulicas modulares, obras de refuerzo de ruta y grúas.","requirements":["Plataformas modulares hidráulicas (SPMT) sobre 250 t","Referencias de transporte de transformadores","Capacidad de estudio de ruta y refuerzo de puentes"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw35v000x52bhm25zypdz', 'tbea-om-solar-services', 'O&M technical services for two utility-scale solar plants', 'Multi-year operations & maintenance services for two 150 MW photovoltaic plants: preventive and corrective maintenance, module cleaning, thermographic inspections, spare-parts management and 24/7 monitoring handover.', 'maintenance', 'STANDARD', 'cms5cw34j000d52bhnzfmk6l7', 'Argentina', 'AR', NULL, 6000000, 10000000, '2026-09-20 00:00:00', '["O&M portfolio above 300 MW PV","Certified HV switching personnel","CMMS-based maintenance reporting"]', 'OPEN', 58, '2026-07-29 00:38:18.883', '2026-07-29 00:38:18.883', '{"es":{"title":"Servicios técnicos de O&M para dos plantas solares utility-scale","description":"Servicios de operación y mantenimiento plurianuales para dos plantas fotovoltaicas de 150 MW: mantenimiento preventivo y correctivo, limpieza de módulos, inspecciones termográficas, gestión de repuestos y traspaso a monitoreo 24/7.","requirements":["Portafolio de O&M sobre 300 MW fotovoltaicos","Personal certificado para maniobras de alta tensión","Reportería de mantenimiento basada en CMMS"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw368001152bhdsnk1iia', 'tlp-geotech-survey-closed', 'Geotechnical survey campaign — coastal section', 'Completed campaign of 240 boreholes and geophysical lines along the coastal section of the water transport system. Published for reference; applications are closed.', 'technical_services', 'STANDARD', 'cms5cw342000752bh8b5g83mg', 'Chile', 'CL', NULL, 1500000, 3000000, NULL, '["Offshore/coastal drilling experience"]', 'CLOSED', 204, '2026-07-29 00:38:18.897', '2026-07-29 00:38:18.897', '{"es":{"title":"Campaña de sondajes geotécnicos — tramo costero","description":"Campaña finalizada de 240 sondajes y líneas geofísicas a lo largo del tramo costero del sistema de transporte de agua. Publicada como referencia; las postulaciones están cerradas.","requirements":["Experiencia en perforación costera / offshore"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw34z000j52bhrflk2ez6', 'tlp-epc-pumping-stations', 'EPC contractor for three 12 MW pumping stations', 'Engineering, procurement and construction of three high-head pumping stations (12 MW installed each) including electrical rooms, surge protection and SCADA integration for a concentrate pipeline in Peru. Contract under FIDIC Yellow Book with milestone-based payments.', 'epc', 'EPC_TENDER', 'cms5cw342000752bh8b5g83mg', 'Peru', 'PE', 'Arequipa', 90000000, 140000000, '2026-11-30 00:00:00', '["FIDIC Yellow Book track record","At least two pumping or compression stations delivered as EPC","In-country civil works capacity (Peru)","ISO 9001 / ISO 45001 certified"]', 'OPEN', 205, '2026-07-29 00:38:18.851', '2026-07-29 00:40:13.983', '{"es":{"title":"Contratista EPC para tres estaciones de bombeo de 12 MW","description":"Ingeniería, procura y construcción de tres estaciones de bombeo de alta presión (12 MW instalados cada una), incluyendo salas eléctricas, protección antiariete e integración SCADA para un mineroducto de concentrado en Perú. Contrato bajo FIDIC Libro Amarillo con pagos por hitos.","requirements":["Track record bajo FIDIC Libro Amarillo","Al menos dos estaciones de bombeo o compresión entregadas como EPC","Capacidad de obras civiles en el país (Perú)","Certificación ISO 9001 / ISO 45001"]}}');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt", translations) VALUES ('cms5cw364000z52bhlxex1d3m', 'ag-epc-crushing-conveyor', 'EPC turnkey — primary crushing & overland conveyor (2,800 t/h)', 'Full EPC package for a 2,800 t/h primary crushing station and a 7.4 km overland conveyor serving an iron ore expansion in Minas Gerais: engineering, procurement, civil works, structural and electromechanical erection, commissioning and performance tests. Lump-sum turnkey with liquidated damages on schedule and throughput.', 'epc', 'EPC_TENDER', 'cms5cw34b000a52bhbwbjcu5u', 'Brazil', 'BR', 'Belo Horizonte', 120000000, 180000000, '2026-12-01 00:00:00', '["Turnkey EPC references above USD 100M in mining","In-house structural & electromechanical erection capacity","Performance-test guarantees (throughput and availability)","ISO 9001 / ISO 45001 certified"]', 'OPEN', 135, '2026-07-29 00:38:18.892', '2026-07-29 00:40:45.304', '{"es":{"title":"EPC llave en mano — chancado primario y correa overland (2.800 t/h)","description":"Paquete EPC completo para una estación de chancado primario de 2.800 t/h y una correa transportadora overland de 7,4 km para una expansión de mineral de hierro en Minas Gerais: ingeniería, procura, obras civiles, montaje estructural y electromecánico, puesta en marcha y pruebas de desempeño. Suma alzada llave en mano con multas por plazo y throughput.","requirements":["Referencias EPC llave en mano sobre USD 100M en minería","Capacidad propia de montaje estructural y electromecánico","Garantías de pruebas de desempeño (throughput y disponibilidad)","Certificación ISO 9001 / ISO 45001"]}}');
