INSERT INTO public."Offer" (id, "projectId", "investorId", amount, type, "equityPct", message, status, "createdAt", "updatedAt") VALUES ('cms5cw3ch005r52bhmobky05l', 'cms5cw395002c52bhru1vzxng', 'cms5cw33u000452bh9pndya97', 135000000, 'equity_stake', 55, 'Northbridge Infrastructure Fund is pleased to submit this non-binding expression of interest for a 55% equity stake, subject to confirmatory due diligence. We have completed three water infrastructure transactions in LatAm since 2022 and can move to binding terms within 60 days of data room access.', 'IN_DISCUSSION', '2026-07-29 00:38:19.121', '2026-07-29 00:38:19.121');
INSERT INTO public."Offer" (id, "projectId", "investorId", amount, type, "equityPct", message, status, "createdAt", "updatedAt") VALUES ('cms5cw3ck005t52bhc4koh3jp', 'cms5cw3ac003r52bh3tujqcrj', 'cms5cw33u000452bh9pndya97', 178000000, 'full_acquisition', NULL, 'We propose a full acquisition at the indicated valuation midpoint, financed 60/40 debt-equity with committed financing letters available. Exclusivity of 45 days requested.', 'PENDING', '2026-07-29 00:38:19.124', '2026-07-29 00:38:19.124');
