INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw3ff007a52bhbto7ojl4', 'latam-water-infrastructure-mandate', 'LatAm Water & Desalination Platform Build-up', 'Northbridge Infrastructure Fund is deploying its third fund into water infrastructure across Latin America. We target operating desalination plants, water transmission and industrial water-supply assets with contracted, USD-denominated revenues. Preference for majority stakes alongside proven local operators; single-asset tickets of USD 80–250M with capacity to fund expansions.', 'cms5cw33u000452bh9pndya97', '["water"]', '["CL","PE","MX"]', '["operating","expansion"]', '["partial_sale","full_sale"]', 80000000, 250000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-29 00:38:19.227', '2026-07-29 00:38:19.227', '{"es":{"title":"Construcción de Plataforma de Agua y Desalinización en LatAm","description":"Northbridge Infrastructure Fund está desplegando su tercer fondo en infraestructura hídrica en América Latina. Buscamos plantas desalinizadoras en operación, activos de conducción de agua y de suministro de agua industrial con ingresos contratados y denominados en USD. Preferencia por participaciones mayoritarias junto a operadores locales de trayectoria comprobada; tickets por activo individual de USD 80–250M con capacidad para financiar expansiones."}}');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw3fl007c52bhw36f6ad9', 'copper-battery-metals-mandate', 'Copper & Battery Metals — Development Capital', 'Pacific Rim Strategic Holdings seeks copper and lithium exposure across the Americas and Australia, from advanced exploration through construction. We provide staged development capital, streaming structures or outright acquisition, with technical teams able to move to binding terms within 90 days. Ticket range USD 100–500M.', 'cms5cw3fa007852bhylacrt7z', '["mining"]', '["CL","PE","AU","US"]', '["greenfield","construction","operating"]', '["capital_raise","full_sale","partial_sale"]', 100000000, 500000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-29 00:38:19.234', '2026-07-29 00:38:19.234', '{"es":{"title":"Cobre y Metales para Baterías — Capital de Desarrollo","description":"Pacific Rim Strategic Holdings busca exposición a cobre y litio en las Américas y Australia, desde exploración avanzada hasta construcción. Ofrecemos capital de desarrollo por etapas, estructuras de streaming o adquisición total, con equipos técnicos capaces de llegar a términos vinculantes en un plazo de 90 días. Rango de ticket: USD 100–500M."}}');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw3fp007e52bhvyavcsei', 'iberia-latam-renewables-yield-mandate', 'Operating Renewables — Iberia & Mexico Yield Portfolio', 'Baltica Infrastructure Partners is acquiring operating solar and wind assets in Spain and Mexico for a yield-focused permanent-capital vehicle. Contracted or partially contracted revenue profiles preferred; tickets of USD 100–300M per transaction, with appetite for portfolios up to USD 600M.', 'cms5cw3f5007752bhteli9p6h', '["energy"]', '["ES","MX"]', '["operating"]', '["full_sale","partial_sale"]', 100000000, 300000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-29 00:38:19.237', '2026-07-29 00:38:19.237', '{"es":{"title":"Renovables en Operación — Portafolio de Yield en Iberia y México","description":"Baltica Infrastructure Partners está adquiriendo activos solares y eólicos en operación en España y México para un vehículo de capital permanente enfocado en yield. Se prefieren perfiles de ingresos contratados o parcialmente contratados; tickets de USD 100–300M por transacción, con apetito por portafolios de hasta USD 600M."}}');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw3fs007g52bh2uwfu9ia', 'green-hydrogen-jv-mandate', 'Green Hydrogen & Ammonia — Strategic JV Partner', 'Industrial group with committed offtake in Northern Europe seeks joint-venture positions in utility-scale green hydrogen and ammonia projects with world-class renewable resources. We contribute FEED funding, offtake and engineering capacity for projects targeting FID within 4 years. Investment capacity of USD 500M–1.5B per platform.', 'cms5cw3f5007752bhteli9p6h', '["energy"]', '["CL","MA","AU"]', '["greenfield","construction"]', '["joint_venture","capital_raise"]', 500000000, 1500000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-29 00:38:19.24', '2026-07-29 00:38:19.24', '{"es":{"title":"Hidrógeno Verde y Amoníaco — Socio Estratégico para Joint Venture","description":"Grupo industrial con offtake comprometido en el norte de Europa busca posiciones de joint venture en proyectos de hidrógeno verde y amoníaco a escala industrial con recursos renovables de clase mundial. Aportamos financiamiento de FEED, offtake y capacidad de ingeniería para proyectos con FID previsto dentro de 4 años. Capacidad de inversión de USD 500–1.500 millones por plataforma."}}');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw3fv007i52bh5yldotgl', 'agro-export-platforms-mandate', 'Export Agriculture Platforms — Growth Equity', 'Pacific Rim Strategic Holdings allocates growth equity to vertically integrated agro-export platforms with secured water rights and retail programs in premium markets. Berries, avocado, nuts and permanent crops preferred; tickets USD 30–250M for minority or control positions.', 'cms5cw3fa007852bhylacrt7z', '["agro"]', '["PE","CL","MX","AU"]', '["operating","expansion"]', '["capital_raise","partial_sale","full_sale"]', 30000000, 250000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-29 00:38:19.244', '2026-07-29 00:38:19.244', '{"es":{"title":"Plataformas Agroexportadoras — Capital de Crecimiento","description":"Pacific Rim Strategic Holdings asigna capital de crecimiento (growth equity) a plataformas agroexportadoras verticalmente integradas con derechos de agua asegurados y programas de retail en mercados premium. Se prefieren berries, palta/aguacate, frutos secos y cultivos permanentes; tickets de USD 30–250M para posiciones minoritarias o de control."}}');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt", translations) VALUES ('cms5cw3fy007k52bhu1nf467h', 'core-ports-logistics-confidential', 'Core+ Ports & Terminals — Confidential Search', 'On behalf of a sovereign-adjacent investor, Northbridge is conducting a confidential search for operating port terminals and cold-chain logistics assets in Southern Europe and the Gulf. Take-or-pay or contracted revenue required; tickets USD 50–250M. This mandate is not publicly listed.', 'cms5cw33u000452bh9pndya97', '["ports"]', '["ES","AE"]', '["operating"]', '["partial_sale","full_sale"]', 50000000, 250000000, NULL, NULL, NULL, false, 'PUBLISHED', NULL, '2026-07-29 00:38:19.247', '2026-07-29 00:38:19.247', '{"es":{"title":"Puertos y Terminales Core+ — Búsqueda Confidencial","description":"Por encargo de un inversionista de perfil cuasi soberano, Northbridge conduce una búsqueda confidencial de terminales portuarios en operación y activos de logística de cadena de frío en el sur de Europa y el Golfo. Se requieren ingresos take-or-pay o contratados; tickets de USD 50–250M. Este mandato no está listado públicamente."}}');
