INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3g6007n52bh6g76jc8e', 'grade-a-copper-cathodes-antofagasta', 'SELL', 'copper_cathodes', 'Grade A Copper Cathodes — 2,000 t/month, FOB Antofagasta', 'LME-registered Grade A copper cathodes (99.9935% Cu) produced at an established electro-winning operation in northern Chile. Consistent monthly availability of 2,000 tonnes with capacity to scale to 3,000 tonnes under an annual frame contract. Full traceability, ISO 9001 production and certificates of analysis issued by an independent laboratory for every lot.', '[{"label":"Purity","value":"99.9935% Cu (LME Grade A)"},{"label":"Format","value":"Cathode sheets, ~125 kg, steel-strapped bundles"},{"label":"Registration","value":"LME-registered brand"},{"label":"Packing","value":"Bundles of ~2.2 t"}]', '2,000 t/month', 'contract', 'CL', NULL, 'FOB', 'Port of Antofagasta, Chile', 'indexed', 'LME Cash Settlement minus 45 USD/t', NULL, '[{"name":"Certificate of Analysis (sample lot)","url":"https://example.com/docs/sample.pdf","isConfidential":true},{"name":"Product Specification Sheet","url":"https://example.com/docs/sample.pdf","isConfidential":false}]', 'PUBLISHED', true, NULL, 640, 'cms5cw33m000252bhto8ylae9', '2026-07-29 00:38:19.255', '2026-07-29 00:38:19.255', '{"es":{"title":"Cátodos de Cobre Grado A — 2.000 t/mes, FOB Antofagasta","description":"Cátodos de cobre Grado A registrados en la LME (99,9935% Cu) producidos en una operación de electroobtención consolidada en el norte de Chile. Disponibilidad mensual constante de 2.000 toneladas con capacidad de escalar a 3.000 toneladas bajo un contrato marco anual. Trazabilidad completa, producción bajo ISO 9001 y certificados de análisis emitidos por un laboratorio independiente para cada lote.","specs":[{"label":"Pureza","value":"99,9935% Cu (LME Grado A)"},{"label":"Formato","value":"Láminas de cátodo, ~125 kg, atados zunchados con fleje de acero"},{"label":"Registro","value":"Marca registrada en la LME"},{"label":"Embalaje","value":"Atados de ~2,2 t"}],"volume":"2.000 t/mes","deliveryLocation":"Puerto de Antofagasta, Chile","priceDetails":"LME Cash Settlement menos 45 USD/t"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3gb007p52bh6ai4uk11', 'copper-concentrate-26-southern-peru', 'SELL', 'copper_concentrate', 'Copper Concentrate 26% Cu — 10,000 t/quarter, CIF Main Asian Port', 'Clean copper concentrate from a producing mine in southern Peru: 26% Cu with gold and silver credits, low arsenic (<0.15%). Quarterly parcels of 10,000 wmt under an annual offtake frame, shipped in bulk from Matarani. Standard TC/RC terms with quotational period negotiable.', '[{"label":"Cu grade","value":"26% (typical)"},{"label":"Au / Ag credits","value":"3.1 g/t Au · 68 g/t Ag"},{"label":"Arsenic","value":"<0.15%"},{"label":"Moisture","value":"8.5%"}]', '10,000 wmt/quarter', 'contract', 'PE', NULL, 'CIF', 'Main Asian port (buyer''s option)', 'indexed', 'LME basis, benchmark TC/RC, QP M+1', NULL, '[{"name":"Typical Assay Certificate","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', true, NULL, 512, 'cms5cw33i000152bhh8po64vs', '2026-07-29 00:38:19.259', '2026-07-29 00:38:19.259', '{"es":{"title":"Concentrado de Cobre 26% Cu — 10.000 t/trimestre, CIF Puerto Principal de Asia","description":"Concentrado de cobre limpio de una mina en producción en el sur de Perú: 26% Cu con créditos de oro y plata, bajo arsénico (<0,15%). Lotes trimestrales de 10.000 wmt bajo un contrato marco anual de offtake, embarcados a granel desde Matarani. Términos TC/RC estándar con período de cotización (QP) negociable.","specs":[{"label":"Ley de Cu","value":"26% (típico)"},{"label":"Créditos de Au / Ag","value":"3,1 g/t Au · 68 g/t Ag"},{"label":"Arsénico","value":"<0,15%"},{"label":"Humedad","value":"8,5%"}],"volume":"10.000 wmt/trimestre","deliveryLocation":"Puerto principal de Asia (a opción del comprador)","priceDetails":"Base LME, TC/RC benchmark, QP M+1"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3ge007r52bhtjfq71es', 'battery-grade-lithium-carbonate-chile', 'SELL', 'lithium_carbonate', 'Battery-Grade Lithium Carbonate — 300 t/month, FOB Chilean Port', 'Battery-grade lithium carbonate (≥99.5% Li₂CO₃) from brine operations in the Atacama basin. Monthly availability of 300 tonnes in 500 kg big bags, containerized. Suitable for cathode manufacturing; magnetic impurities controlled below 300 ppb. Long-term supply contracts preferred; spot parcels considered.', '[{"label":"Purity","value":"≥99.5% Li₂CO₃"},{"label":"Magnetic impurities","value":"<300 ppb"},{"label":"Packing","value":"500 kg big bags, 20 t per container"}]', '300 t/month', 'contract', 'CL', NULL, 'FOB', 'Port of Angamos, Chile', 'indexed', 'Fastmarkets Li₂CO₃ CIF Asia index minus 3%', NULL, '[{"name":"Battery-Grade Specification","url":"https://example.com/docs/sample.pdf","isConfidential":false},{"name":"Full Impurity Panel (CoA)","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', true, NULL, 738, 'cms5cw33m000252bhto8ylae9', '2026-07-29 00:38:19.263', '2026-07-29 00:38:19.263', '{"es":{"title":"Carbonato de Litio Grado Batería — 300 t/mes, FOB Puerto Chileno","description":"Carbonato de litio grado batería (≥99,5% Li₂CO₃) proveniente de operaciones de salmuera en la cuenca de Atacama. Disponibilidad mensual de 300 toneladas en big bags de 500 kg, containerizado. Apto para fabricación de cátodos; impurezas magnéticas controladas por debajo de 300 ppb. Se prefieren contratos de suministro de largo plazo; se consideran lotes spot.","specs":[{"label":"Pureza","value":"≥99,5% Li₂CO₃"},{"label":"Impurezas magnéticas","value":"<300 ppb"},{"label":"Embalaje","value":"Big bags de 500 kg, 20 t por contenedor"}],"volume":"300 t/mes","deliveryLocation":"Puerto de Angamos, Chile","priceDetails":"Índice Fastmarkets Li₂CO₃ CIF Asia menos 3%"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3gi007t52bh5savcuch', 'iron-ore-fines-62-port-hedland', 'SELL', 'iron_ore', 'Iron Ore Fines 62% Fe — 50,000 t Spot Parcels, FOB Port Hedland', 'Standard 62% Fe iron ore fines available in spot parcels of 50,000 tonnes from Port Hedland. Low phosphorus and alumina; sized 0–10 mm. Immediate laycans available; larger contract volumes negotiable for H2.', '[{"label":"Fe content","value":"62% (typical)"},{"label":"Sizing","value":"0–10 mm fines"},{"label":"Phosphorus","value":"0.07%"},{"label":"Alumina","value":"2.1%"}]', '50,000 t/parcel (spot)', 'spot', 'AU', NULL, 'FOB', 'Port Hedland, Australia', 'indexed', 'Platts IODEX 62% Fe minus 2.5 USD/t', NULL, '[]', 'PUBLISHED', true, NULL, 431, 'cms5cw33q000352bh44m6uk3g', '2026-07-29 00:38:19.266', '2026-07-29 00:38:19.266', '{"es":{"title":"Finos de Mineral de Hierro 62% Fe — Lotes Spot de 50.000 t, FOB Port Hedland","description":"Finos de mineral de hierro estándar de 62% Fe disponibles en lotes spot de 50.000 toneladas desde Port Hedland. Bajo fósforo y baja alúmina; granulometría 0–10 mm. Laycans inmediatos disponibles; volúmenes contractuales mayores negociables para el segundo semestre.","specs":[{"label":"Contenido de Fe","value":"62% (típico)"},{"label":"Granulometría","value":"Finos de 0–10 mm"},{"label":"Fósforo","value":"0,07%"},{"label":"Alúmina","value":"2,1%"}],"volume":"50.000 t/lote (spot)","deliveryLocation":"Port Hedland, Australia","priceDetails":"Platts IODEX 62% Fe menos 2,5 USD/t"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3gm007v52bhf38k1vmd', 'molybdenum-oxide-chile', 'SELL', 'molybdenum_oxide', 'Molybdenum Oxide (Tech Grade) — 200 t/month, CIF Rotterdam', 'Technical-grade molybdenum oxide (57% Mo min) in drums, by-product of a Chilean copper operation. Monthly volume of 200 tonnes, shipped containerized to Rotterdam or main European port. Annual contract with quarterly price reviews preferred.', '[{"label":"Mo content","value":"57% min"},{"label":"Packing","value":"250 kg drums"}]', '200 t/month', 'contract', 'CL', NULL, 'CIF', 'Rotterdam, Netherlands', 'indexed', 'Platts Mo oxide mean, quarterly review', NULL, '[]', 'PUBLISHED', false, NULL, 210, 'cms5cw33m000252bhto8ylae9', '2026-07-29 00:38:19.27', '2026-07-29 00:38:19.27', '{"es":{"title":"Óxido de Molibdeno (Grado Técnico) — 200 t/mes, CIF Rotterdam","description":"Óxido de molibdeno grado técnico (57% Mo mín.) en tambores, subproducto de una operación cuprífera chilena. Volumen mensual de 200 toneladas, embarcado containerizado a Rotterdam o puerto principal europeo. Se prefiere contrato anual con revisiones trimestrales de precio.","specs":[{"label":"Contenido de Mo","value":"57% mín."},{"label":"Embalaje","value":"Tambores de 250 kg"}],"volume":"200 t/mes","deliveryLocation":"Rotterdam, Países Bajos","priceDetails":"Media Platts de óxido de Mo, revisión trimestral"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3gp007x52bhwaijt78e', 'zinc-concentrate-52-callao', 'SELL', 'zinc_concentrate', 'Zinc Concentrate 52% Zn — 5,000 t/month, FOB Callao', 'High-grade zinc concentrate (52% Zn, 380 g/t Ag credits) from a producing polymetallic mine in central Peru. Monthly liftings of 5,000 wmt from Callao under annual frames; standard smelter terms.', '[{"label":"Zn grade","value":"52%"},{"label":"Ag credits","value":"380 g/t"},{"label":"Fe","value":"6.2%"}]', '5,000 wmt/month', 'contract', 'PE', NULL, 'FOB', 'Port of Callao, Peru', 'indexed', 'LME Zn basis, benchmark TC', NULL, '[{"name":"Typical Assay","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', true, NULL, 356, 'cms5cw33q000352bh44m6uk3g', '2026-07-29 00:38:19.274', '2026-07-29 00:38:19.274', '{"es":{"title":"Concentrado de Zinc 52% Zn — 5.000 t/mes, FOB Callao","description":"Concentrado de zinc de alta ley (52% Zn, créditos de 380 g/t Ag) de una mina polimetálica en producción en el centro de Perú. Embarques mensuales de 5.000 wmt desde el Callao bajo contratos marco anuales; términos estándar de fundición.","specs":[{"label":"Ley de Zn","value":"52%"},{"label":"Créditos de Ag","value":"380 g/t"},{"label":"Fe","value":"6,2%"}],"volume":"5.000 wmt/mes","deliveryLocation":"Puerto del Callao, Perú","priceDetails":"Base LME Zn, TC benchmark"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3gt007z52bh259aez6j', 'gold-dore-lima', 'SELL', 'gold_dore', 'Gold Doré 92% Au — 50 kg/month, EXW Lima', 'Gold doré bars (92% Au, 6% Ag typical) from a formalized medium-scale producer in Peru, with full chain-of-custody documentation and export permits. Monthly availability of 50 kg; refining and logistics support available for qualified buyers. Compliance dossier (LBMA-aligned responsible sourcing) shared under NDA.', '[{"label":"Au content","value":"92% (typical)"},{"label":"Ag content","value":"6% (typical)"},{"label":"Bar size","value":"~12.5 kg"}]', '50 kg/month', 'contract', 'PE', NULL, 'EXW', 'Lima, Peru (secure facility)', 'indexed', 'LBMA PM fix minus 1.2%, assay-adjusted', NULL, '[{"name":"Responsible Sourcing Dossier","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', false, NULL, 489, 'cms5cw33q000352bh44m6uk3g', '2026-07-29 00:38:19.277', '2026-07-29 00:38:19.277', '{"es":{"title":"Doré de Oro 92% Au — 50 kg/mes, EXW Lima","description":"Barras de doré de oro (92% Au, 6% Ag típico) de un productor formalizado de mediana escala en Perú, con documentación completa de cadena de custodia y permisos de exportación. Disponibilidad mensual de 50 kg; apoyo en refinación y logística disponible para compradores calificados. Dossier de cumplimiento (abastecimiento responsable alineado con LBMA) compartido bajo NDA.","specs":[{"label":"Contenido de Au","value":"92% (típico)"},{"label":"Contenido de Ag","value":"6% (típico)"},{"label":"Tamaño de barra","value":"~12,5 kg"}],"volume":"50 kg/mes","deliveryLocation":"Lima, Perú (instalación de seguridad)","priceDetails":"LBMA PM fix menos 1,2%, ajustado por ensaye"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3gw008152bhthg1k9te', 'premium-fishmeal-callao', 'SELL', 'fishmeal', 'Premium Fishmeal 67% Protein — 3,000 t/quarter, FOB Callao', 'Super-prime fishmeal (67% protein min, TVN <100) from certified Peruvian producers, IFFO RS chain of custody. Quarterly parcels of 3,000 tonnes in 50 kg bags or big bags. Annual supply programs available with fixed premium over the Peruvian export reference.', '[{"label":"Protein","value":"67% min"},{"label":"TVN","value":"<100 mg/100g"},{"label":"Certification","value":"IFFO RS"}]', '3,000 t/quarter', 'contract', 'PE', NULL, 'FOB', 'Port of Callao, Peru', 'fixed', 'USD 1,720/t FOB (current quarter)', NULL, '[]', 'PUBLISHED', true, NULL, 298, 'cms5cw33q000352bh44m6uk3g', '2026-07-29 00:38:19.28', '2026-07-29 00:38:19.28', '{"es":{"title":"Harina de Pescado Premium 67% Proteína — 3.000 t/trimestre, FOB Callao","description":"Harina de pescado super prime (67% proteína mín., TVN <100) de productores peruanos certificados, con cadena de custodia IFFO RS. Lotes trimestrales de 3.000 toneladas en sacos de 50 kg o big bags. Programas de suministro anuales disponibles con prima fija sobre la referencia de exportación peruana.","specs":[{"label":"Proteína","value":"67% mín."},{"label":"TVN","value":"<100 mg/100g"},{"label":"Certificación","value":"IFFO RS"}],"volume":"3.000 t/trimestre","deliveryLocation":"Puerto del Callao, Perú","priceDetails":"USD 1.720/t FOB (trimestre en curso)"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3h0008352bhqg21fdfw', 'bek-wood-pulp-brazil', 'SELL', 'wood_pulp', 'Bleached Eucalyptus Kraft Pulp — 8,000 t/month, FOB Santos', 'BEK market pulp from a certified Brazilian producer (FSC), 8,000 tonnes monthly in unitized bales. Suitable for tissue and printing grades. Annual contracts with quarterly volume flexibility of ±10%.', '[{"label":"Grade","value":"BEKP (bleached eucalyptus kraft)"},{"label":"Certification","value":"FSC"},{"label":"Brightness","value":"≥89% ISO"}]', '8,000 t/month', 'contract', 'BR', NULL, 'FOB', 'Port of Santos, Brazil', 'indexed', 'PIX BHKP index minus agreed discount', NULL, '[]', 'PUBLISHED', false, NULL, 187, 'cms5cw33m000252bhto8ylae9', '2026-07-29 00:38:19.284', '2026-07-29 00:38:19.284', '{"es":{"title":"Celulosa Kraft Blanqueada de Eucalipto — 8.000 t/mes, FOB Santos","description":"Celulosa de mercado BEK de un productor brasileño certificado (FSC), 8.000 toneladas mensuales en fardos unitizados. Apta para grados tissue y de impresión. Contratos anuales con flexibilidad trimestral de volumen de ±10%.","specs":[{"label":"Grado","value":"BEKP (kraft blanqueada de eucalipto)"},{"label":"Certificación","value":"FSC"},{"label":"Blancura","value":"≥89% ISO"}],"volume":"8.000 t/mes","deliveryLocation":"Puerto de Santos, Brasil","priceDetails":"Índice PIX BHKP menos descuento acordado"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3h3008552bhhnausrgn', 'buy-copper-cathodes-gulf', 'BUY', 'copper_cathodes', 'Buying: Grade A Copper Cathodes — 1,500–3,000 t/month, Gulf Destination', 'Gulf Metals Trading FZE seeks Grade A copper cathodes for long-term supply into Gulf and South Asian re-rolling customers. Monthly volumes of 1,500–3,000 tonnes under 12-month frames with LCs from first-class banks. LME-registered brands preferred; non-registered considered with full assay history.', '[{"label":"Purity required","value":"99.99% Cu min"},{"label":"Payment","value":"LC at sight, first-class bank"}]', '1,500–3,000 t/month', 'contract', NULL, 'AE', 'CIF', 'Jebel Ali, UAE', 'indexed', 'LME basis plus negotiable premium', NULL, '[]', 'PUBLISHED', true, NULL, 402, 'cms5cw3g2007l52bhrm6o3oen', '2026-07-29 00:38:19.287', '2026-07-29 00:38:19.287', '{"es":{"title":"Se Compra: Cátodos de Cobre Grado A — 1.500–3.000 t/mes, Destino Golfo","description":"Gulf Metals Trading FZE busca cátodos de cobre Grado A para suministro de largo plazo a clientes de relaminación en el Golfo y el sur de Asia. Volúmenes mensuales de 1.500–3.000 toneladas bajo contratos marco de 12 meses con LCs de bancos de primera línea. Se prefieren marcas registradas en la LME; se consideran marcas no registradas con historial completo de ensayes.","specs":[{"label":"Pureza requerida","value":"99,99% Cu mín."},{"label":"Pago","value":"LC a la vista, banco de primera línea"}],"volume":"1.500–3.000 t/mes","deliveryLocation":"Jebel Ali, EAU","priceDetails":"Base LME más prima negociable"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3h7008752bhjsyl5syz', 'buy-lithium-carbonate-us', 'BUY', 'lithium_carbonate', 'Buying: Battery-Grade Lithium Carbonate — 200 t/month, US Cathode Plant', 'US cathode-materials manufacturer seeks battery-grade lithium carbonate under multi-year contract, 200 t/month ramping to 500 t/month by 2028. Qualification samples required; IRA-compliant origins prioritized.', '[{"label":"Purity required","value":"≥99.5% Li₂CO₃, battery grade"},{"label":"Qualification","value":"2-lot sampling process"}]', '200 t/month (ramping to 500 t)', 'contract', NULL, 'US', 'FOB', 'US Gulf port', 'indexed', 'Fastmarkets index basis, collar structure', NULL, '[]', 'PUBLISHED', true, NULL, 377, 'cms5cw3fa007852bhylacrt7z', '2026-07-29 00:38:19.291', '2026-07-29 00:38:19.291', '{"es":{"title":"Se Compra: Carbonato de Litio Grado Batería — 200 t/mes, Planta de Cátodos en EE. UU.","description":"Fabricante estadounidense de materiales para cátodos busca carbonato de litio grado batería bajo contrato multianual, 200 t/mes escalando a 500 t/mes hacia 2028. Se requieren muestras de calificación; se priorizan orígenes que cumplan con la IRA.","specs":[{"label":"Pureza requerida","value":"≥99,5% Li₂CO₃, grado batería"},{"label":"Calificación","value":"Proceso de muestreo de 2 lotes"}],"volume":"200 t/mes (escalando a 500 t)","deliveryLocation":"Puerto del Golfo de EE. UU.","priceDetails":"Base índice Fastmarkets, estructura de collar"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3ha008952bhhvx3uer6', 'buy-iron-ore-fines-gulf-steel', 'BUY', 'iron_ore', 'Buying: Iron Ore Fines 62% — Spot Parcels 50,000 t, Gulf Steel Mill', 'Integrated steel producer in the Gulf seeks spot parcels of 62% Fe fines, 50,000–80,000 t per shipment, 4–6 shipments per year. Prompt laycans; payment by confirmed LC.', '[{"label":"Fe required","value":"61.5% min"}]', '50,000–80,000 t/parcel', 'spot', NULL, 'AE', 'FOB', 'Loading port at seller''s option', 'indexed', 'Platts IODEX basis', NULL, '[]', 'PUBLISHED', true, NULL, 265, 'cms5cw3g2007l52bhrm6o3oen', '2026-07-29 00:38:19.294', '2026-07-29 00:38:19.294', '{"es":{"title":"Se Compra: Finos de Mineral de Hierro 62% — Lotes Spot de 50.000 t, Acería del Golfo","description":"Productor siderúrgico integrado en el Golfo busca lotes spot de finos de 62% Fe, 50.000–80.000 t por embarque, 4–6 embarques al año. Laycans prontos; pago mediante LC confirmada.","specs":[{"label":"Fe requerido","value":"61,5% mín."}],"volume":"50.000–80.000 t/lote","deliveryLocation":"Puerto de carga a opción del vendedor","priceDetails":"Base Platts IODEX"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3hd008b52bhgktm7ll9', 'buy-fishmeal-aquafeed-spain', 'BUY', 'fishmeal', 'Buying: Super-Prime Fishmeal — 2,500 t/quarter, Spanish Aquafeed Group', 'European aquafeed producer seeks super-prime fishmeal (66%+ protein) on annual programs, 2,500 tonnes quarterly, delivered FOB origin with IFFO RS certification mandatory.', '[{"label":"Protein required","value":"66% min"},{"label":"Certification","value":"IFFO RS mandatory"}]', '2,500 t/quarter', 'contract', NULL, 'ES', 'FOB', 'Origin port', 'fixed', 'Fixed quarterly, negotiable', NULL, '[]', 'PUBLISHED', false, NULL, 143, 'cms5cw3f5007752bhteli9p6h', '2026-07-29 00:38:19.297', '2026-07-29 00:38:19.297', '{"es":{"title":"Se Compra: Harina de Pescado Super Prime — 2.500 t/trimestre, Grupo Español de Alimento Acuícola","description":"Productor europeo de alimento acuícola busca harina de pescado super prime (66%+ de proteína) en programas anuales, 2.500 toneladas trimestrales, entregada FOB origen con certificación IFFO RS obligatoria.","specs":[{"label":"Proteína requerida","value":"66% mín."},{"label":"Certificación","value":"IFFO RS obligatoria"}],"volume":"2.500 t/trimestre","deliveryLocation":"Puerto de origen","priceDetails":"Fijo trimestral, negociable"}}');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt", translations) VALUES ('cms5cw3hi008d52bhn81kdlrm', 'buy-copper-concentrate-smelter-spain', 'BUY', 'copper_concentrate', 'Buying: Clean Copper Concentrates — 40,000 t/year, European Smelter', 'European custom smelter seeks clean copper concentrates (24%+ Cu, low As) for annual frames totaling 40,000 tonnes, CIF Huelva. Benchmark TC/RC; QP flexible. Long-term relationships with producing mines preferred over trader material.', '[{"label":"Cu required","value":"24% min"},{"label":"As limit","value":"<0.2%"}]', '40,000 t/year', 'contract', NULL, 'ES', 'CIF', 'Port of Huelva, Spain', 'indexed', 'LME basis, benchmark TC/RC', NULL, '[]', 'PUBLISHED', true, NULL, 231, 'cms5cw3f5007752bhteli9p6h', '2026-07-29 00:38:19.302', '2026-07-29 00:38:19.302', '{"es":{"title":"Se Compra: Concentrados de Cobre Limpios — 40.000 t/año, Fundición Europea","description":"Fundición europea de maquila busca concentrados de cobre limpios (24%+ Cu, bajo As) para contratos marco anuales por un total de 40.000 toneladas, CIF Huelva. TC/RC benchmark; QP flexible. Se prefieren relaciones de largo plazo con minas productoras por sobre material de traders.","specs":[{"label":"Cu requerido","value":"24% mín."},{"label":"Límite de As","value":"<0,2%"}],"volume":"40.000 t/año","deliveryLocation":"Puerto de Huelva, España","priceDetails":"Base LME, TC/RC benchmark"}}');
