-- =============================================================================
-- VORTAMAX Global — demo seed data (PostgreSQL / Supabase)
-- =============================================================================
-- Generated from the output of prisma/seed.ts on a clean PostgreSQL 16
-- database, dumped in foreign-key-safe order. Includes the Spanish content
-- overlay (translations column) and @vortamax.global demo accounts.
--
-- PREREQUISITE: the schema must already exist and be EMPTY — apply BOTH
-- migrations first (prisma/migrations/20260728233421_init +
-- 20260729003754_main_features_and_ecosystem_i18n), or run
-- prisma/supabase-01-schema-baseline.sql after pasting the init by hand.
--
-- USAGE: paste this entire file into the Supabase SQL Editor and run it once.
-- Everything loads inside a single transaction: it either succeeds completely
-- or leaves the database untouched. A guard aborts if data already exists.
--
-- Demo password for every account: assetmax123 (stored bcrypt-hashed).
-- =============================================================================

BEGIN;

-- Abort immediately if the database is not empty.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public."User" LIMIT 1) THEN
    RAISE EXCEPTION 'Seed aborted: public."User" already contains data. Run this script only on a freshly migrated, empty schema.';
  END IF;
END
$$;

